/*
 * t_vfp.c -- host tests for package V17, n2a32_vfp.c.
 *
 * The class function is called directly on a struct n2a32_cpu whose mem->base is a 16 MiB calloc
 * (guest addresses below 16 MiB), as the package task prescribes.  Every instruction word comes
 * from enc_v17.h, generated by run_tests.sh from vectors.s / vectors_t32.s through llvm-mc; no
 * encoding is typed by hand.  Every expected register, flag and memory value below is a literal
 * worked out from the ARM ARM pseudocode and the IEEE-754 formats, not from the implementation
 * (the arithmetic identities used are noted next to the non-obvious ones).
 */
#include <fenv.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "n2a32.h"
#include "n2a32_fp_util.h"
#include "enc_v17.h"

#define GUEST_SIZE (16u << 20)
#define PC_IN 0x10008u
#define NPC_IN 0x10000u

#define CUM (N2AFP_IOC | N2AFP_DZC | N2AFP_OFC | N2AFP_UFC | N2AFP_IXC | N2AFP_IDC)

static uint8_t *g_base;
static struct n2a32_mem M;
static struct n2a32_cpu C;
static const char *g_name;
static int g_checks, g_fails;

/* ------------------------------------------------------------------ n2a32_mmio hooks (core normally) */

uint32_t n2a32_mmio_load(struct n2a32_mem *m, uint32_t a, unsigned bytes)
{ (void)m; (void)a; (void)bytes; return 0; }
void n2a32_mmio_store(struct n2a32_mem *m, uint32_t a, unsigned bytes, uint32_t v)
{ (void)m; (void)a; (void)bytes; (void)v; }

/* ------------------------------------------------------------------ checks */

static void ck(int cond, const char *what, uint64_t got, uint64_t want)
{
	g_checks++;
	if (!cond) {
		g_fails++;
		if (g_fails <= 60)
			fprintf(stderr, "FAIL [%s] %s: got 0x%016llx want 0x%016llx\n",
				g_name, what, (unsigned long long)got, (unsigned long long)want);
	}
}

static void eq(const char *what, uint64_t got, uint64_t want) { ck(got == want, what, got, want); }

static void begin(const char *name)
{
	memset(&C, 0, sizeof C);
	C.mem = &M;
	C.r[15] = PC_IN;
	C.next_pc = NPC_IN;
	g_name = name;
}

static int run(uint32_t enc)
{
	int rc = n2a32_vfp(&C, enc);
	ck(rc == N2A32_OK || rc == N2A32_UNDEF, "return OK/UNDEF", (uint64_t)rc, 0);
	return rc;
}

static void ok(uint32_t enc)
{
	int rc = run(enc);
	ck(rc == N2A32_OK, "return OK", (uint64_t)rc, N2A32_OK);
	/* This class never branches: PC state must be untouched. */
	eq("r15 unchanged", C.r[15], PC_IN);
	eq("next_pc unchanged", C.next_pc, NPC_IN);
}

static void undef(uint32_t enc)
{
	int rc = run(enc);
	ck(rc == N2A32_UNDEF, "return UNDEF", (uint64_t)rc, N2A32_UNDEF);
	eq("r15 unchanged", C.r[15], PC_IN);
	eq("next_pc unchanged", C.next_pc, NPC_IN);
}

/* ------------------------------------------------------------------ register / memory helpers */

static void sset(unsigned s, uint32_t bits) { C.d[(s >> 1) & 31u].u32[s & 1u] = bits; }
static uint32_t sget(unsigned s) { return C.d[(s >> 1) & 31u].u32[s & 1u]; }
static void dset(unsigned d, uint64_t bits) { C.d[d & 31u].u64 = bits; }
static uint64_t dget(unsigned d) { return C.d[d & 31u].u64; }

static void w32(uint32_t a, uint32_t v) { memcpy(g_base + a, &v, 4); }
static uint32_t r32(uint32_t a) { uint32_t v; memcpy(&v, g_base + a, 4); return v; }
static void w64(uint32_t a, uint64_t v) { memcpy(g_base + a, &v, 8); }
static uint64_t r64(uint32_t a) { uint64_t v; memcpy(&v, g_base + a, 8); return v; }

/* ------------------------------------------------------------------ generic forms */

static void bin32(const char *nm, uint32_t enc, unsigned rd, unsigned rn, unsigned rm,
		  uint32_t a, uint32_t b, uint32_t acc, uint32_t want, uint32_t flags)
{
	begin(nm);
	sset(rn, a); sset(rm, b); sset(rd, acc);
	ok(enc);
	eq("result", sget(rd), want);
	eq("cumulative flags", C.fpscr & CUM, flags);
}

static void bin64(const char *nm, uint32_t enc, unsigned rd, unsigned rn, unsigned rm,
		  uint64_t a, uint64_t b, uint64_t acc, uint64_t want, uint32_t flags)
{
	begin(nm);
	dset(rn, a); dset(rm, b); dset(rd, acc);
	ok(enc);
	eq("result", dget(rd), want);
	eq("cumulative flags", C.fpscr & CUM, flags);
}

static void un32(const char *nm, uint32_t enc, unsigned rd, unsigned rm, uint32_t a,
		 uint32_t want, uint32_t flags)
{
	begin(nm);
	sset(rm, a);
	ok(enc);
	eq("result", sget(rd), want);
	eq("cumulative flags", C.fpscr & CUM, flags);
}

static void un64(const char *nm, uint32_t enc, unsigned rd, unsigned rm, uint64_t a,
		 uint64_t want, uint32_t flags)
{
	begin(nm);
	dset(rm, a);
	ok(enc);
	eq("result", dget(rd), want);
	eq("cumulative flags", C.fpscr & CUM, flags);
}

static void cmp32(const char *nm, uint32_t enc, uint32_t a, uint32_t b, uint32_t want_nzcv, uint32_t flags)
{
	begin(nm);
	sset(0, a); sset(1, b); sset(2, a); sset(3, b); sset(4, a); sset(5, a);
	ok(enc);
	eq("FPSCR NZCV", C.fpscr & 0xF0000000u, want_nzcv);
	eq("cumulative flags", C.fpscr & CUM, flags);
}

static void cmp64(const char *nm, uint32_t enc, uint64_t a, uint64_t b, uint64_t want_nzcv, uint32_t flags)
{
	begin(nm);
	dset(0, a); dset(1, b); dset(2, a); dset(3, b); dset(4, a); dset(5, a);
	ok(enc);
	eq("FPSCR NZCV", C.fpscr & 0xF0000000u, (uint32_t)want_nzcv);
	eq("cumulative flags", C.fpscr & CUM, flags);
}

/* ------------------------------------------------------------------ VLDR / VSTR */

static void t_ldst(void)
{
	begin("VLDR s0,[r0]");
	C.r[0] = 0x11000; w32(0x11000, 0x11223344);
	ok(ENC_vldr_s0_r0);
	eq("s0", sget(0), 0x11223344);
	eq("r0", C.r[0], 0x11000);

	begin("VLDR s4,[r1,#4]");
	C.r[1] = 0x11100; w32(0x11104, 0x55667788);
	ok(ENC_vldr_s4_r1_p4);
	eq("s4", sget(4), 0x55667788);

	begin("VLDR s8,[r2,#-8]");
	C.r[2] = 0x11200; w32(0x111F8, 0x99AABBCC);
	ok(ENC_vldr_s8_r2_m8);
	eq("s8", sget(8), 0x99AABBCC);

	begin("VLDR d1,[r3,#16]");
	C.r[3] = 0x11300; w64(0x11310, 0x0123456789ABCDEFULL);
	ok(ENC_vldr_d1_r3_p16);
	eq("d1", dget(1), 0x0123456789ABCDEFULL);

	begin("VLDR d17,[r4,#8]");
	C.r[4] = 0x11400; w64(0x11408, 0xFEDCBA9876543210ULL);
	ok(ENC_vldr_d17_r4_p8);
	eq("d17", dget(17), 0xFEDCBA9876543210ULL);

	begin("VLDR s2,[pc,#8]");
	w32((PC_IN & ~3u) + 8u, 0x13579BDF);
	ok(ENC_vldr_s2_pc);
	eq("s2", sget(2), 0x13579BDF);

	begin("VLDR s3,[sp,#-4]");
	C.r[13] = 0x11500; w32(0x114FC, 0x2468ACE0);
	ok(ENC_vldr_s3_sp_m4);
	eq("s3", sget(3), 0x2468ACE0);

	begin("VSTR s0,[r0]");
	C.r[0] = 0x11600; sset(0, 0xCAFEBABE);
	ok(ENC_vstr_s0_r0);
	eq("mem", r32(0x11600), 0xCAFEBABE);

	begin("VSTR s6,[r1,#12]");
	C.r[1] = 0x11700; sset(6, 0x0BADF00D);
	ok(ENC_vstr_s6_r1_p12);
	eq("mem", r32(0x1170C), 0x0BADF00D);

	begin("VSTR d2,[r2,#-16]");
	C.r[2] = 0x11800; dset(2, 0x1122334455667788ULL);
	ok(ENC_vstr_d2_r2_m16);
	eq("mem", r64(0x117F0), 0x1122334455667788ULL);

	begin("VSTR d18,[sp]");
	C.r[13] = 0x11900; dset(18, 0x8877665544332211ULL);
	ok(ENC_vstr_d18_sp);
	eq("mem", r64(0x11900), 0x8877665544332211ULL);

	begin("VSTR literal is unallocated");
	C.r[15] = PC_IN;
	undef(ENC_vstr_s1_pc);
}

/* ------------------------------------------------------------------ VLDM / VSTM / VPUSH / VPOP / FLDMX */

static void t_ldm(void)
{
	begin("VLDMIA r0,{s0-s2}");
	C.r[0] = 0x12000;
	w32(0x12000, 0x3F800000); w32(0x12004, 0x40000000); w32(0x12008, 0x40400000);
	ok(ENC_vldmia_r0_s0_s2);
	eq("s0", sget(0), 0x3F800000);
	eq("s1", sget(1), 0x40000000);
	eq("s2", sget(2), 0x40400000);
	eq("r0", C.r[0], 0x12000);

	begin("VLDMIA r1!,{d0-d1}");
	C.r[1] = 0x12100;
	w64(0x12100, 0x3FF0000000000000ULL); w64(0x12108, 0x4000000000000000ULL);
	ok(ENC_vldmia_r1w_d0_d1);
	eq("d0", dget(0), 0x3FF0000000000000ULL);
	eq("d1", dget(1), 0x4000000000000000ULL);
	eq("r1", C.r[1], 0x12110);

	begin("VLDMDB r2!,{d2-d3}");
	C.r[2] = 0x12300;
	w64(0x122F0, 0x1111111111111111ULL); w64(0x122F8, 0x2222222222222222ULL);
	ok(ENC_vldmdb_r2w_d2_d3);
	eq("d2", dget(2), 0x1111111111111111ULL);
	eq("d3", dget(3), 0x2222222222222222ULL);
	eq("r2", C.r[2], 0x122F0);

	begin("VSTMIA r3,{s4-s5}");
	C.r[3] = 0x12400; sset(4, 0xDEADBEEF); sset(5, 0x01234567);
	ok(ENC_vstmia_r3_s4_s5);
	eq("mem0", r32(0x12400), 0xDEADBEEF);
	eq("mem1", r32(0x12404), 0x01234567);
	eq("r3", C.r[3], 0x12400);

	begin("VSTMIA r4!,{d4-d5}");
	C.r[4] = 0x12500; dset(4, 0xAAAABBBBCCCCDDDDULL); dset(5, 0x1111222233334444ULL);
	ok(ENC_vstmia_r4w_d4_d5);
	eq("mem0", r64(0x12500), 0xAAAABBBBCCCCDDDDULL);
	eq("mem1", r64(0x12508), 0x1111222233334444ULL);
	eq("r4", C.r[4], 0x12510);

	begin("VSTMDB r5!,{s8-s9}");
	C.r[5] = 0x12600; sset(8, 0x55555555); sset(9, 0x66666666);
	ok(ENC_vstmdb_r5w_s8_s9);
	eq("mem0", r32(0x125F8), 0x55555555);
	eq("mem1", r32(0x125FC), 0x66666666);
	eq("r5", C.r[5], 0x125F8);

	begin("VPUSH {s0-s3}");
	C.r[13] = 0x12800;
	sset(0, 1); sset(1, 2); sset(2, 3); sset(3, 4);
	ok(ENC_vpush_s0_s3);
	eq("sp", C.r[13], 0x127F0);
	eq("mem0", r32(0x127F0), 1);
	eq("mem3", r32(0x127FC), 4);

	begin("VPOP {d0-d1}");
	C.r[13] = 0x12900;
	w64(0x12900, 0x7FF8000000000001ULL); w64(0x12908, 0x8000000000000000ULL);
	ok(ENC_vpop_d0_d1);
	eq("d0", dget(0), 0x7FF8000000000001ULL);
	eq("d1", dget(1), 0x8000000000000000ULL);
	eq("sp", C.r[13], 0x12910);

	begin("VPUSH {d16-d17}");
	C.r[13] = 0x12A00;
	dset(16, 0x0123456789ABCDEFULL); dset(17, 0xFEDCBA9876543210ULL);
	ok(ENC_vpush_d16_d17);
	eq("sp", C.r[13], 0x129F0);
	eq("mem0", r64(0x129F0), 0x0123456789ABCDEFULL);
	eq("mem1", r64(0x129F8), 0xFEDCBA9876543210ULL);

	begin("VPOP {s16-s19}");
	C.r[13] = 0x12B00;
	w32(0x12B00, 0x10); w32(0x12B04, 0x11); w32(0x12B08, 0x12); w32(0x12B0C, 0x13);
	ok(ENC_vpop_s16_s19);
	eq("s16", sget(16), 0x10);
	eq("s19", sget(19), 0x13);
	eq("sp", C.r[13], 0x12B10);

	begin("VLDMIA r6,{s0-s31} (32 registers)");
	C.r[6] = 0x12C00;
	for (unsigned i = 0; i < 32; i++) w32(0x12C00 + i * 4u, 0x40000000u + i);
	ok(ENC_vldm_r6_s0_s31);
	eq("s0", sget(0), 0x40000000);
	eq("s31", sget(31), 0x4000001F);
	eq("r6", C.r[6], 0x12C00);

	begin("FLDMIAX r0,{d0-d1} (odd imm8)");
	C.r[0] = 0x12D00;
	w64(0x12D00, 0x3FF0000000000000ULL); w64(0x12D08, 0x4000000000000000ULL);
	w32(0x12D10, 0x0000001F);	/* extra word -> FPSCR */
	ok(ENC_fldmiax_r0_d0_d1);
	eq("d0", dget(0), 0x3FF0000000000000ULL);
	eq("d1", dget(1), 0x4000000000000000ULL);
	eq("fpscr", C.fpscr, 0x0000001F);
	eq("r0", C.r[0], 0x12D00);

	begin("FLDMIAX r1!,{d2-d3}");
	C.r[1] = 0x12E00;
	w64(0x12E00, 0xAAAABBBBCCCCDDDDULL); w64(0x12E08, 0x1111222233334444ULL);
	w32(0x12E10, 0x00000001);
	ok(ENC_fldmiax_r1w_d2_d3);
	eq("d2", dget(2), 0xAAAABBBBCCCCDDDDULL);
	eq("fpscr", C.fpscr, 1);
	eq("r1", C.r[1], 0x12E14);

	begin("FSTMIAX r2,{d4-d5}");
	C.r[2] = 0x12F00;
	dset(4, 0x123456789ABCDEF0ULL); dset(5, 0x0FEDCBA987654321ULL);
	C.fpscr = 0x0000001F;
	ok(ENC_fstmiax_r2_d4_d5);
	eq("mem0", r64(0x12F00), 0x123456789ABCDEF0ULL);
	eq("mem1", r64(0x12F08), 0x0FEDCBA987654321ULL);
	eq("extra", r32(0x12F10), 0x0000001F);
	eq("r2", C.r[2], 0x12F00);

	begin("FSTMIAX r3!,{d6}");
	C.r[3] = 0x13000; dset(6, 0x0123456789ABCDEFULL); C.fpscr = 0;
	ok(ENC_fstmiax_r3w_d6);
	eq("mem0", r64(0x13000), 0x0123456789ABCDEFULL);
	eq("extra", r32(0x13008), 0);
	eq("r3", C.r[3], 0x1300C);

	begin("FLDMDBX r4!,{d8-d9}");
	C.r[4] = 0x13200;
	w64(0x131EC, 0x1111111111111111ULL); w64(0x131F4, 0x2222222222222222ULL);
	w32(0x131FC, 0x00000005);
	ok(ENC_fldmdbx_r4w_d8_d9);
	eq("d8", dget(8), 0x1111111111111111ULL);
	eq("d9", dget(9), 0x2222222222222222ULL);
	eq("fpscr", C.fpscr, 5);
	eq("r4", C.r[4], 0x131EC);

	begin("FSTMDBX r5!,{d10}");
	C.r[5] = 0x13300; dset(10, 0x9999999999999999ULL); C.fpscr = 0x10;
	ok(ENC_fstmdbx_r5w_d10);
	eq("mem0", r64(0x132F4), 0x9999999999999999ULL);
	eq("extra", r32(0x132FC), 0x10);
	eq("r5", C.r[5], 0x132F4);
}

/* ------------------------------------------------------------------ VMOV core <-> FP */

static void t_mov_core(void)
{
	begin("VMOV r0,s0");
	sset(0, 0x11223344); ok(ENC_vmov_r0_s0); eq("r0", C.r[0], 0x11223344);

	begin("VMOV r1,s5");
	sset(5, 0xAABBCCDD); ok(ENC_vmov_r1_s5); eq("r1", C.r[1], 0xAABBCCDD);

	begin("VMOV s2,r3");
	C.r[3] = 0xDEADBEEF; ok(ENC_vmov_s2_r3); eq("s2", sget(2), 0xDEADBEEF);

	begin("VMOV s7,r8");
	C.r[8] = 0x0BADF00D; ok(ENC_vmov_s7_r8); eq("s7", sget(7), 0x0BADF00D);

	begin("VMOV d0,r0,r1");
	C.r[0] = 0x11223344; C.r[1] = 0x55667788;
	ok(ENC_vmov_d0_r0_r1);
	eq("d0", dget(0), 0x5566778811223344ULL);

	begin("VMOV d5,r2,r3");
	C.r[2] = 0xCAFEBABE; C.r[3] = 0xDEADC0DE;
	ok(ENC_vmov_d5_r2_r3);
	eq("d5", dget(5), 0xDEADC0DECAFEBABEULL);

	begin("VMOV d16,r4,r5");
	C.r[4] = 0x00000001; C.r[5] = 0x00000002;
	ok(ENC_vmov_d16_r4_r5);
	eq("d16", dget(16), 0x0000000200000001ULL);

	begin("VMOV r4,r5,d2");
	dset(2, 0xAABBCCDD11223344ULL);
	ok(ENC_vmov_r4_r5_d2);
	eq("r4", C.r[4], 0x11223344);
	eq("r5", C.r[5], 0xAABBCCDD);

	begin("VMOV r6,r7,d10");
	dset(10, 0x0123456789ABCDEFULL);
	ok(ENC_vmov_r6_r7_d10);
	eq("r6", C.r[6], 0x89ABCDEF);
	eq("r7", C.r[7], 0x01234567);

	begin("VMOV s0,s1,r0,r1");
	C.r[0] = 0x3F800000; C.r[1] = 0x40000000;
	ok(ENC_vmov_s0_s1_r0_r1);
	eq("s0", sget(0), 0x3F800000);
	eq("s1", sget(1), 0x40000000);

	begin("VMOV r2,r3,s4,s5");
	sset(4, 0x7FC00001); sset(5, 0x80000000);
	ok(ENC_vmov_r2_r3_s4_s5);
	eq("r2", C.r[2], 0x7FC00001);
	eq("r3", C.r[3], 0x80000000);
}

/* ------------------------------------------------------------------ VMOV lane / VDUP */

static void t_mov_lane(void)
{
	begin("VMOV.32 r0,d0[0]");
	dset(0, 0x1122334455667788ULL); ok(ENC_vmov_r0_d0_0_32); eq("r0", C.r[0], 0x55667788);

	begin("VMOV.32 r1,d0[1]");
	dset(0, 0x1122334455667788ULL); ok(ENC_vmov_r1_d0_1_32); eq("r1", C.r[1], 0x11223344);

	begin("VMOV.32 r2,d5[0]");
	dset(5, 0x99AABBCCDDEEFF00ULL); ok(ENC_vmov_r2_d5_0_32); eq("r2", C.r[2], 0xDDEEFF00);

	begin("VMOV.32 r3,d17[1]");
	dset(17, 0x0123456789ABCDEFULL); ok(ENC_vmov_r3_d17_1_32); eq("r3", C.r[3], 0x01234567);

	begin("VMOV.32 d1[0],r4");
	dset(1, 0xAAAAAAAAAAAAAAAAULL); C.r[4] = 0xDEADBEEF;
	ok(ENC_vmov_d1_0_r4);
	eq("d1", dget(1), 0xAAAAAAAA00000000ULL | 0xDEADBEEFULL);

	begin("VMOV.32 d3[1],r5");
	dset(3, 0x1111111122222222ULL); C.r[5] = 0x33333333;
	ok(ENC_vmov_d3_1_r5);
	eq("d3", dget(3), 0x3333333322222222ULL);

	begin("VMOV.32 d21[1],r6");
	dset(21, 0x4444444444444444ULL); C.r[6] = 0x55555555;
	ok(ENC_vmov_d21_1_r6);
	eq("d21", dget(21), 0x5555555544444444ULL);

	begin("VMOV.U16 r7,d2[2]");
	dset(2, 0x1111222233334444ULL); ok(ENC_vmov_r7_d2_2_16); eq("r7", C.r[7], 0x2222);

	begin("VMOV.U16 r8,d2[3]");
	dset(2, 0x1111222233334444ULL); ok(ENC_vmov_r8_d2_3_u16); eq("r8", C.r[8], 0x1111);

	begin("VMOV.S16 r9,d3[1]");
	dset(3, 0x0000000080010000ULL); ok(ENC_vmov_r9_d3_1_s16); eq("r9", C.r[9], 0xFFFF8001);

	begin("VMOV.16 d4[3],r10");
	dset(4, 0xAAAAAAAAAAAAAAAAULL); C.r[10] = 0x12345678;
	ok(ENC_vmov_d4_3_r10_16);
	eq("d4", dget(4), 0x5678AAAAAAAAAAAAULL);

	begin("VMOV.U8 r11,d5[5]");
	dset(5, 0x0807060504030201ULL); ok(ENC_vmov_r11_d5_5_u8); eq("r11", C.r[11], 6);

	begin("VMOV.S8 r12,d5[6]");
	dset(5, 0x0080000000000000ULL); ok(ENC_vmov_r12_d5_6_s8); eq("r12", C.r[12], 0xFFFFFF80);

	begin("VMOV.8 d6[7],r13 (sp as Rt)");
	dset(6, 0x1111111111111111ULL); C.r[13] = 0xA5;
	ok(ENC_vmov_d6_7_r13_8);
	eq("d6", dget(6), 0xA511111111111111ULL);

	begin("VMOV.8 d6[0],r0");
	dset(6, 0x2222222222222222ULL); C.r[0] = 0x5A;
	ok(ENC_vmov_d6_0_r0_8);
	eq("d6", dget(6), 0x222222222222225AULL);

	begin("VDUP.8 d0,r0");
	C.r[0] = 0x12345678; ok(ENC_vdup_8_d0_r0); eq("d0", dget(0), 0x7878787878787878ULL);

	begin("VDUP.16 d1,r2");
	C.r[2] = 0xABCD1234; ok(ENC_vdup_16_d1_r2); eq("d1", dget(1), 0x1234123412341234ULL);

	begin("VDUP.32 d2,r3");
	C.r[3] = 0xDEADBEEF; ok(ENC_vdup_32_d2_r3); eq("d2", dget(2), 0xDEADBEEFDEADBEEFULL);

	begin("VDUP.8 q0,r4");
	C.r[4] = 0xAA; ok(ENC_vdup_8_q0_r4);
	eq("d0", dget(0), 0xAAAAAAAAAAAAAAAAULL);
	eq("d1", dget(1), 0xAAAAAAAAAAAAAAAAULL);

	begin("VDUP.16 q1,r5");
	C.r[5] = 0x0000BEEF; ok(ENC_vdup_16_q1_r5);
	eq("d2", dget(2), 0xBEEFBEEFBEEFBEEFULL);
	eq("d3", dget(3), 0xBEEFBEEFBEEFBEEFULL);

	begin("VDUP.32 q2,r6");
	C.r[6] = 0x11223344; ok(ENC_vdup_32_q2_r6);
	eq("d4", dget(4), 0x1122334411223344ULL);
	eq("d5", dget(5), 0x1122334411223344ULL);

	begin("VDUP.32 d16,r7");
	C.r[7] = 0x55667788; ok(ENC_vdup_32_d16_r7); eq("d16", dget(16), 0x5566778855667788ULL);
}

/* ------------------------------------------------------------------ VMOV immediate / register */

static void t_mov_imm(void)
{
	begin("VMOV.F32 #1.0"); ok(ENC_vmov_f32_s0_p1); eq("s0", sget(0), 0x3F800000);
	begin("VMOV.F32 #-2.5"); ok(ENC_vmov_f32_s1_m2_5); eq("s1", sget(1), 0xC0200000);
	begin("VMOV.F32 #0.125"); ok(ENC_vmov_f32_s4_p0_125); eq("s4", sget(4), 0x3E000000);
	begin("VMOV.F64 #1.0"); ok(ENC_vmov_f64_d0_p1); eq("d0", dget(0), 0x3FF0000000000000ULL);
	begin("VMOV.F64 #-2.5"); ok(ENC_vmov_f64_d1_m2_5); eq("d1", dget(1), 0xC004000000000000ULL);
	begin("VMOV.F64 #3.75"); ok(ENC_vmov_f64_d16_p3_75); eq("d16", dget(16), 0x400E000000000000ULL);

	/* The VFP imm8 format has no zero encoding: 0x00 is +2.0 and 0x80 is -2.0. */
	begin("VMOV.F32 #2.0"); ok(ENC_vmov_f32_s5_p2); eq("s5", sget(5), 0x40000000);
	begin("VMOV.F32 #-2.0"); ok(ENC_vmov_f32_s6_m2); eq("s6", sget(6), 0xC0000000);
	begin("VMOV.F32 #-1.0"); ok(ENC_vmov_f32_s7_m1); eq("s7", sget(7), 0xBF800000);
	begin("VMOV.F32 #4.0"); ok(ENC_vmov_f32_s8_p4); eq("s8", sget(8), 0x40800000);
	begin("VMOV.F64 #2.0"); ok(ENC_vmov_f64_d3_p2); eq("d3", dget(3), 0x4000000000000000ULL);
	begin("VMOV.F64 #-2.0"); ok(ENC_vmov_f64_d4_m2); eq("d4", dget(4), 0xC000000000000000ULL);
	begin("VMOV.F64 #-1.0"); ok(ENC_vmov_f64_d5_m1); eq("d5", dget(5), 0xBFF0000000000000ULL);


	begin("VMOV.F32 s0,s1");
	sset(1, 0x7FC00001); ok(ENC_vmov_f32_s0_s1); eq("s0", sget(0), 0x7FC00001);
	begin("VMOV.F32 s5,s9");
	sset(9, 0x80000000); ok(ENC_vmov_f32_s5_s9); eq("s5", sget(5), 0x80000000);
	begin("VMOV.F64 d0,d1");
	dset(1, 0x7FF8000000000001ULL); ok(ENC_vmov_f64_d0_d1); eq("d0", dget(0), 0x7FF8000000000001ULL);
	begin("VMOV.F64 d7,d20");
	dset(20, 0x8000000000000000ULL); ok(ENC_vmov_f64_d7_d20); eq("d7", dget(7), 0x8000000000000000ULL);
}

/* ------------------------------------------------------------------ VMRS / VMSR */

static void t_sysreg(void)
{
	begin("VMRS r0,FPSCR");
	C.fpscr = 0x1234009F; ok(ENC_vmrs_r0); eq("r0", C.r[0], 0x1234009F);

	begin("VMRS r12,FPSCR");
	C.fpscr = 0xFBC0009F; ok(ENC_vmrs_r12); eq("r12", C.r[12], 0xFBC0009F);

	begin("VMRS APSR_nzcv,FPSCR");
	C.fpscr = 0xA0000000; ok(ENC_vmrs_apsr);
	eq("n", C.n, 1); eq("z", C.z, 0); eq("c", C.cf, 1); eq("v", C.v, 0);

	begin("VMRS APSR_nzcv,FPSCR (Z set)");
	C.fpscr = 0x40000000; ok(ENC_vmrs_apsr);
	eq("n", C.n, 0); eq("z", C.z, 1); eq("c", C.cf, 0); eq("v", C.v, 0);

	begin("VMSR FPSCR,r0");
	C.r[0] = 0xFFFFFFFF; ok(ENC_vmsr_r0); eq("fpscr", C.fpscr, 0xFBC0009F);

	begin("VMSR FPSCR,r5");
	C.r[5] = 0x00000000; C.fpscr = 0xFFFFFFFF; ok(ENC_vmsr_r5); eq("fpscr", C.fpscr, 0);

	begin("VMSR FPSCR rounding mode");
	C.r[0] = 0x00C00000; ok(ENC_vmsr_r0); eq("RMode", (C.fpscr >> 22) & 3u, 3);

}

static void t_undef(void)
{
	begin("VMRS r0,FPEXC (not implemented)"); undef(ENC_vmrs_r0_fpexc); eq("r0", C.r[0], 0);
	begin("VMSR FPEXC,r0 (not implemented)"); C.fpscr = 5; undef(ENC_vmsr_r0_fpexc); eq("fpscr", C.fpscr, 5);
	begin("VMRS r0,FPSID (not implemented)"); undef(ENC_vmrs_r0_fpsid);
	begin("VMRS r0,MVFR0 (not implemented)"); undef(ENC_vmrs_r0_mvfr0);
}

/* ------------------------------------------------------------------ arithmetic */

static void t_arith(void)
{
	/* VADD */
	bin32("VADD.F32 1.5+2.25", ENC_vadd_f32, 0, 1, 2, 0x3FC00000, 0x40100000, 0, 0x40700000, 0);
	bin32("VADD.F32 -1+1", ENC_vadd_f32, 0, 1, 2, 0xBF800000, 0x3F800000, 0, 0x00000000, 0);
	bin32("VADD.F32 0.1+0", ENC_vadd_f32_hi, 10, 11, 12, 0x3DCCCCCD, 0x00000000, 0, 0x3DCCCCCD, 0);
	bin32("VADD.F32 overflow", ENC_vadd_f32, 0, 1, 2, 0x7F7FFFFF, 0x7F7FFFFF, 0, 0x7F800000,
	      N2AFP_OFC | N2AFP_IXC);
	bin32("VADD.F32 -0+-0", ENC_vadd_f32_negzero, 20, 21, 22, 0x80000000, 0x80000000, 0, 0x80000000, 0);
	bin32("VADD.F32 inf+-inf", ENC_vadd_f32, 0, 1, 2, 0x7F800000, 0xFF800000, 0, 0x7FC00000, N2AFP_IOC);
	bin64("VADD.F64 1.5+2.25", ENC_vadd_f64, 0, 1, 2, 0x3FF8000000000000ULL,
	      0x4002000000000000ULL, 0, 0x400E000000000000ULL, 0);
	bin64("VADD.F64 -0+-0", ENC_vadd_f64_hi, 10, 11, 12, 0x8000000000000000ULL,
	      0x8000000000000000ULL, 0, 0x8000000000000000ULL, 0);
	bin64("VADD.F64 overflow", ENC_vadd_f64, 0, 1, 2, 0x7FEFFFFFFFFFFFFFULL,
	      0x7FEFFFFFFFFFFFFFULL, 0, 0x7FF0000000000000ULL, N2AFP_OFC | N2AFP_IXC);

	/* VSUB */
	bin32("VSUB.F32 1.5-2.25", ENC_vsub_f32, 0, 1, 2, 0x3FC00000, 0x40100000, 0, 0xBF400000, 0);
	bin32("VSUB.F32 -1.5-(-1.5)", ENC_vsub_f32_hi, 10, 11, 12, 0xBFC00000, 0xBFC00000, 0, 0, 0);
	bin64("VSUB.F64 1.5-2.25", ENC_vsub_f64, 0, 1, 2, 0x3FF8000000000000ULL,
	      0x4002000000000000ULL, 0, 0xBFE8000000000000ULL, 0);
	bin64("VSUB.F64 inf-inf", ENC_vsub_f64_hi, 10, 11, 12, 0x7FF0000000000000ULL,
	      0x7FF0000000000000ULL, 0, 0x7FF8000000000000ULL, N2AFP_IOC);

	/* VMUL / VNMUL */
	bin32("VMUL.F32 3*2", ENC_vmul_f32, 0, 1, 2, 0x40400000, 0x40000000, 0, 0x40C00000, 0);
	bin32("VMUL.F32 -2*3", ENC_vmul_f32_hi, 10, 11, 12, 0xC0000000, 0x40400000, 0, 0xC0C00000, 0);
	bin32("VMUL.F32 0*inf", ENC_vmul_f32, 0, 1, 2, 0x00000000, 0x7F800000, 0, 0x7FC00000, N2AFP_IOC);
	bin32("VNMUL.F32 -(2*3)", ENC_vnmul_f32, 0, 1, 2, 0x40000000, 0x40400000, 0, 0xC0C00000, 0);
	bin32("VNMUL.F32 -(2*-3)", ENC_vnmul_f32_hi, 10, 11, 12, 0x40000000, 0xC0400000, 0, 0x40C00000, 0);
	bin64("VMUL.F64 3*2", ENC_vmul_f64, 0, 1, 2, 0x4008000000000000ULL,
	      0x4000000000000000ULL, 0, 0x4018000000000000ULL, 0);
	bin64("VMUL.F64 0*inf", ENC_vmul_f64_hi, 10, 11, 12, 0, 0x7FF0000000000000ULL, 0,
	      0x7FF8000000000000ULL, N2AFP_IOC);
	bin64("VNMUL.F64 -(2*3)", ENC_vnmul_f64, 0, 1, 2, 0x4000000000000000ULL,
	      0x4008000000000000ULL, 0, 0xC018000000000000ULL, 0);

	/* VDIV */
	bin32("VDIV.F32 1/4", ENC_vdiv_f32, 0, 1, 2, 0x3F800000, 0x40800000, 0, 0x3E800000, 0);
	bin32("VDIV.F32 1/0", ENC_vdiv_f32_hi, 10, 11, 12, 0x3F800000, 0x00000000, 0, 0x7F800000, N2AFP_DZC);
	bin32("VDIV.F32 -1/0", ENC_vdiv_f32, 0, 1, 2, 0xBF800000, 0x00000000, 0, 0xFF800000, N2AFP_DZC);
	bin32("VDIV.F32 0/0", ENC_vdiv_f32, 0, 1, 2, 0x00000000, 0x00000000, 0, 0x7FC00000, N2AFP_IOC);
	bin64("VDIV.F64 1/4", ENC_vdiv_f64, 0, 1, 2, 0x3FF0000000000000ULL,
	      0x4010000000000000ULL, 0, 0x3FD0000000000000ULL, 0);
	bin64("VDIV.F64 -1/0", ENC_vdiv_f64_hi, 10, 11, 12, 0xBFF0000000000000ULL, 0, 0,
	      0xFFF0000000000000ULL, N2AFP_DZC);

	/* VMLA / VMLS / VNMLA / VNMLS */
	bin32("VMLA.F32 2+3*4", ENC_vmla_f32, 0, 1, 2, 0x40400000, 0x40800000, 0x40000000, 0x41600000, 0);
	bin32("VMLA.F32 -2+3*4", ENC_vmla_f32_hi, 10, 11, 12, 0x40400000, 0x40800000, 0xC0000000, 0x41200000, 0);
	bin32("VMLS.F32 2-3*4", ENC_vmls_f32, 0, 1, 2, 0x40400000, 0x40800000, 0x40000000, 0xC1200000, 0);
	bin32("VMLS.F32 -1-0.5*2", ENC_vmls_f32_hi, 10, 11, 12, 0x3F000000, 0x40000000, 0xBF800000, 0xC0000000, 0);
	bin32("VNMLA.F32 -(2+3*4)", ENC_vnmla_f32, 0, 1, 2, 0x40400000, 0x40800000, 0x40000000, 0xC1600000, 0);
	bin32("VNMLS.F32 -(2-3*4)", ENC_vnmls_f32, 0, 1, 2, 0x40400000, 0x40800000, 0x40000000, 0x41200000, 0);
	bin64("VMLA.F64 2+3*4", ENC_vmla_f64, 0, 1, 2, 0x4008000000000000ULL,
	      0x4010000000000000ULL, 0x4000000000000000ULL, 0x402C000000000000ULL, 0);
	bin64("VMLA.F64 1+2*2", ENC_vmla_f64_hi, 10, 11, 12, 0x4000000000000000ULL,
	      0x4000000000000000ULL, 0x3FF0000000000000ULL, 0x4014000000000000ULL, 0);
	bin64("VMLS.F64 2-3*4", ENC_vmls_f64, 0, 1, 2, 0x4008000000000000ULL,
	      0x4010000000000000ULL, 0x4000000000000000ULL, 0xC024000000000000ULL, 0);
	bin64("VNMLA.F64", ENC_vnmla_f64, 0, 1, 2, 0x4008000000000000ULL,
	      0x4010000000000000ULL, 0x4000000000000000ULL, 0xC02C000000000000ULL, 0);
	bin64("VNMLS.F64", ENC_vnmls_f64, 0, 1, 2, 0x4008000000000000ULL,
	      0x4010000000000000ULL, 0x4000000000000000ULL, 0x4024000000000000ULL, 0);

	/* VFMA / VFMS / VFNMA / VFNMS.  Cancellation identity: (1+2^-23)(1-2^-23) = 1-2^-46;
	 * with addend -1 the fused result is exactly -2^-46 (0xA8800000), while an unfused
	 * multiply would round the product to 1.0 and the addition to +0. */
	bin32("VFMA.F32 fused cancellation", ENC_vfma_f32, 0, 1, 2, 0x3F800001, 0x3F7FFFFF,
	      0xBF800000, 0x337FFFFE, 0);
	bin32("VFMA.F32 2+3*4", ENC_vfma_f32_hi, 10, 11, 12, 0x40400000, 0x40800000, 0x40000000, 0x41600000, 0);
	bin32("VFMS.F32 1-(1+2^-24-2^-47)", ENC_vfms_f32, 0, 1, 2, 0x3F800001, 0x3F7FFFFF,
	      0x3F800000, 0xB37FFFFE, 0);
	bin32("VFNMA.F32 -(1+1+2^-24-2^-47)", ENC_vfnma_f32, 0, 1, 2, 0x3F800001, 0x3F7FFFFF,
	      0x3F800000, 0xC0000000, N2AFP_IXC);
	bin32("VFNMS.F32 -(1-(1+2^-24-2^-47))", ENC_vfnms_f32, 0, 1, 2, 0x3F800001, 0x3F7FFFFF,
	      0x3F800000, 0x337FFFFE, 0);
	bin64("VFMA.F64 fused cancellation", ENC_vfma_f64, 0, 1, 2,
	      0x3FF0000000000001ULL, 0x3FEFFFFFFFFFFFFFULL, 0xBFF0000000000000ULL,
	      0x3C9FFFFFFFFFFFFEULL, 0);
	bin64("VFMS.F64", ENC_vfms_f64, 0, 1, 2, 0x3FF0000000000001ULL, 0x3FEFFFFFFFFFFFFFULL,
	      0x3FF0000000000000ULL, 0xBC9FFFFFFFFFFFFEULL, 0);
	bin64("VFNMA.F64", ENC_vfnma_f64, 0, 1, 2, 0x3FF0000000000001ULL, 0x3FEFFFFFFFFFFFFFULL,
	      0x3FF0000000000000ULL, 0xC000000000000000ULL, N2AFP_IXC);
	bin64("VFNMS.F64", ENC_vfnms_f64, 0, 1, 2, 0x3FF0000000000001ULL, 0x3FEFFFFFFFFFFFFFULL,
	      0x3FF0000000000000ULL, 0x3C9FFFFFFFFFFFFEULL, 0);

	/* NaN selection and default NaN */
	bin32("VADD qNaN first", ENC_vadd_f32, 0, 1, 2, 0x7FC12345, 0x3F800000, 0, 0x7FC12345, 0);
	bin32("VADD sNaN quieted", ENC_vadd_f32, 0, 1, 2, 0x7F812345, 0x3F800000, 0, 0x7FC12345, N2AFP_IOC);
	bin32("VADD qNaN order", ENC_vadd_f32, 0, 1, 2, 0x7FC11111, 0x7FC22222, 0, 0x7FC11111, 0);
	bin32("VADD sNaN order (second wins)", ENC_vadd_f32, 0, 1, 2, 0x7FC11111, 0x7F822222, 0,
	      0x7FC22222, N2AFP_IOC);
	bin32("VADD qNaN preserves sign", ENC_vadd_f32, 0, 1, 2, 0xFFC12345, 0x3F800000, 0, 0xFFC12345, 0);
	bin64("VADD.F64 qNaN", ENC_vadd_f64, 0, 1, 2, 0x7FF8000000001234ULL,
	      0x3FF0000000000000ULL, 0, 0x7FF8000000001234ULL, 0);
	bin64("VADD.F64 sNaN", ENC_vadd_f64, 0, 1, 2, 0x7FF0000000001234ULL,
	      0x3FF0000000000000ULL, 0, 0x7FF8000000001234ULL, N2AFP_IOC);

	/* DN=1 makes every NaN result the default NaN */
	begin("VADD DN=1 qNaN");
	C.fpscr = N2AFP_DN;
	sset(1, 0x7FC12345); sset(2, 0x3F800000);
	ok(ENC_vadd_f32);
	eq("result", sget(0), 0x7FC00000);
	eq("flags", C.fpscr & CUM, 0);

	begin("VADD DN=1 default NaN is positive even for -NaN");
	C.fpscr = N2AFP_DN;
	sset(1, 0xFFC12345); sset(2, 0x3F800000);
	ok(ENC_vadd_f32);
	eq("result", sget(0), 0x7FC00000);

	begin("VADD DN=1 sNaN still sets IOC");
	C.fpscr = N2AFP_DN;
	sset(1, 0x7F812345); sset(2, 0x3F800000);
	ok(ENC_vadd_f32);
	eq("result", sget(0), 0x7FC00000);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VSQRT DN=1 sNaN still sets IOC");
	C.fpscr = N2AFP_DN; sset(9, 0x7F800001);
	ok(ENC_vsqrt_f32);
	eq("s8", sget(8), 0x7FC00000);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVT.F64.F32 DN=1 sNaN still sets IOC");
	C.fpscr = N2AFP_DN; sset(1, 0x7F800001);
	ok(ENC_vcvt_f64_f32);
	eq("d0", dget(0), 0x7FF8000000000000ULL);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	/* FPSCR.FZ */
	begin("VADD FZ=1 flushes subnormal input");
	C.fpscr = N2AFP_FZ;
	sset(1, 0x00000001); sset(2, 0x3F800000);
	ok(ENC_vadd_f32);
	eq("result", sget(0), 0x3F800000);
	eq("flags", C.fpscr & CUM, N2AFP_IDC);

	begin("VMUL FZ=1 flushes subnormal result");
	C.fpscr = N2AFP_FZ;
	sset(1, 0x00800000); sset(2, 0x3F000000);	/* min normal * 0.5 = exact subnormal */
	ok(ENC_vmul_f32);
	eq("result", sget(0), 0x00000000);
	eq("flags", C.fpscr & CUM, N2AFP_UFC | N2AFP_IXC);

	begin("VMUL FZ=0 keeps exact subnormal result");
	sset(1, 0x00800000); sset(2, 0x3F000000);
	ok(ENC_vmul_f32);
	eq("result", sget(0), 0x00400000);
	eq("flags", C.fpscr & CUM, 0);

	begin("VDIV FZ=1 underflow sets UFC+IXC");
	C.fpscr = N2AFP_FZ;
	sset(1, 0x00800000); sset(2, 0x40000000);	/* min normal / 2 = exact subnormal */
	ok(ENC_vdiv_f32);
	eq("result", sget(0), 0x00000000);
	ck((C.fpscr & (N2AFP_UFC | N2AFP_IXC)) == (N2AFP_UFC | N2AFP_IXC), "UFC|IXC", C.fpscr & CUM, 0);

	/* rounding mode is taken from FPSCR, not from the host's fenv */
	begin("VADD uses FPSCR.RMode=RM with host FE_UPWARD");
	{
		int entered;
		(void)fesetround(FE_UPWARD);
		entered = fegetround();
		C.fpscr = 2u << 22;		/* RM */
		sset(1, 0x3F800000); sset(2, 0x33000000);	/* 1.0 - 2^-25 */
		ok(ENC_vsub_f32);
		eq("result", sget(0), 0x3F7FFFFF);	/* round toward -inf: 1-2^-23 */
		eq("host rounding restored", (uint64_t)fegetround(), (uint64_t)entered);
		(void)fesetround(FE_TONEAREST);
	}
}

/* ------------------------------------------------------------------ unary */

static void t_unary(void)
{
	un32("VABS.F32 -1.5", ENC_vabs_f32, 0, 1, 0xBFC00000, 0x3FC00000, 0);
	un32("VABS.F32 -0.0", ENC_vabs_f32_hi, 10, 11, 0x80000000, 0x00000000, 0);
	un32("VABS.F32 qNaN keeps NaN sign", ENC_vabs_f32, 0, 1, 0xFFC12345, 0xFFC12345, 0);
	un32("VABS.F32 sNaN", ENC_vabs_f32, 0, 1, 0xFF812345, 0xFFC12345, N2AFP_IOC);
	un64("VABS.F64 -3.5", ENC_vabs_f64, 2, 3, 0xC00C000000000000ULL, 0x400C000000000000ULL, 0);

	un32("VNEG.F32 1.5", ENC_vneg_f32, 4, 5, 0x3FC00000, 0xBFC00000, 0);
	un32("VNEG.F32 +0", ENC_vneg_f32_hi, 14, 15, 0x00000000, 0x80000000, 0);
	un32("VNEG.F32 qNaN keeps sign", ENC_vneg_f32, 4, 5, 0x7FC12345, 0x7FC12345, 0);
	un64("VNEG.F64 -2.0", ENC_vneg_f64, 6, 7, 0xC000000000000000ULL, 0x4000000000000000ULL, 0);

	un32("VSQRT.F32 4", ENC_vsqrt_f32, 8, 9, 0x40800000, 0x40000000, 0);
	un32("VSQRT.F32 2", ENC_vsqrt_f32_hi, 18, 19, 0x40000000, 0x3FB504F3, N2AFP_IXC);
	un32("VSQRT.F32 -1", ENC_vsqrt_f32, 8, 9, 0xBF800000, 0x7FC00000, N2AFP_IOC);
	un32("VSQRT.F32 -0", ENC_vsqrt_f32, 8, 9, 0x80000000, 0x80000000, 0);
	un32("VSQRT.F32 inf", ENC_vsqrt_f32, 8, 9, 0x7F800000, 0x7F800000, 0);
	un32("VSQRT.F32 sNaN", ENC_vsqrt_f32, 8, 9, 0x7F812345, 0x7FC12345, N2AFP_IOC);
	un64("VSQRT.F64 4", ENC_vsqrt_f64, 10, 11, 0x4010000000000000ULL, 0x4000000000000000ULL, 0);
	un64("VSQRT.F64 -1", ENC_vsqrt_f64, 10, 11, 0xBFF0000000000000ULL, 0x7FF8000000000000ULL, N2AFP_IOC);
}

/* ------------------------------------------------------------------ compare */

static void t_compare(void)
{
	cmp32("VCMP.F32 1<2", ENC_vcmp_f32, 0x3F800000, 0x40000000, 0x80000000, 0);
	cmp32("VCMP.F32 2>1", ENC_vcmp_f32, 0x40000000, 0x3F800000, 0x20000000, 0);
	cmp32("VCMP.F32 1==1", ENC_vcmp_f32, 0x3F800000, 0x3F800000, 0x60000000, 0);
	cmp32("VCMP.F32 -0==+0", ENC_vcmp_f32, 0x80000000, 0x00000000, 0x60000000, 0);
	cmp32("VCMP.F32 qNaN unordered", ENC_vcmp_f32, 0x7FC00000, 0x3F800000, 0x30000000, 0);
	cmp32("VCMPE.F32 qNaN invalid", ENC_vcmpe_f32, 0x7FC00000, 0x3F800000, 0x30000000, N2AFP_IOC);
	cmp32("VCMP.F32 sNaN invalid", ENC_vcmp_f32, 0x7F800001, 0x3F800000, 0x30000000, N2AFP_IOC);
	cmp32("VCMP.F32 zero greater", ENC_vcmp_f32_zero, 0x3F800000, 0, 0x20000000, 0);
	cmp32("VCMPE.F32 zero equal", ENC_vcmpe_f32_zero, 0x80000000, 0, 0x60000000, 0);
	cmp64("VCMP.F64 1<2", ENC_vcmp_f64, 0x3FF0000000000000ULL, 0x4000000000000000ULL, 0x80000000, 0);
	cmp64("VCMPE.F64 qNaN", ENC_vcmpe_f64, 0x7FF8000000000000ULL, 0x3FF0000000000000ULL,
	      0x30000000, N2AFP_IOC);
	cmp64("VCMP.F64 zero", ENC_vcmp_f64_zero, 0xBFF0000000000000ULL, 0, 0x80000000, 0);
	cmp64("VCMPE.F64 zero unordered", ENC_vcmpe_f64_zero, 0x7FF4000000000000ULL, 0, 0x30000000, N2AFP_IOC);

	begin("VCMP keeps the other FPSCR bits");
	C.fpscr = N2AFP_IXC | N2AFP_DN;
	sset(0, 0x3F800000); sset(1, 0x3F800000);
	ok(ENC_vcmp_f32);
	eq("nzcv", C.fpscr & 0xF0000000u, 0x60000000);
	eq("other bits", C.fpscr & (N2AFP_IXC | N2AFP_DN), N2AFP_IXC | N2AFP_DN);
}

/* ------------------------------------------------------------------ VCVT */

static void t_cvt(void)
{
	begin("VCVT.F64.F32 1.5");
	sset(1, 0x3FC00000); ok(ENC_vcvt_f64_f32); eq("d0", dget(0), 0x3FF8000000000000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F64.F32 0.1");
	sset(20, 0x3DCCCCCD); ok(ENC_vcvt_f64_f32_hi);
	eq("d16", dget(16), 0x3FB99999A0000000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.F64 2.5");
	dset(3, 0x4004000000000000ULL); ok(ENC_vcvt_f32_f64); eq("s2", sget(2), 0x40200000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.F64 0.1 inexact");
	dset(17, 0x3FB999999999999AULL); ok(ENC_vcvt_f32_f64_hi);
	eq("s20", sget(20), 0x3DCCCCCD); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVT.F32.F64 overflow");
	dset(17, 0x7FEFFFFFFFFFFFFFULL); ok(ENC_vcvt_f32_f64_hi);
	eq("s20", sget(20), 0x7F800000); eq("flags", C.fpscr & CUM, N2AFP_OFC | N2AFP_IXC);

	begin("VCVT.F64.F32 sNaN");
	sset(1, 0x7F800001); ok(ENC_vcvt_f64_f32);
	eq("d0", dget(0), 0x7FF8000020000000ULL);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	/* FP -> integer, round toward zero */
	begin("VCVT.S32.F32 3.7");
	sset(1, 0x406CCCCD); ok(ENC_vcvt_s32_f32); eq("s0", sget(0), 3); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVT.U32.F32 3.7");
	sset(3, 0x406CCCCD); ok(ENC_vcvt_u32_f32); eq("s2", sget(2), 3); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVT.S32.F64 2.9");
	dset(1, 0x4007333333333333ULL); ok(ENC_vcvt_s32_f64); eq("s4", sget(4), 2); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVT.U32.F64 -1.5 saturates to 0");
	dset(2, 0xBFF8000000000000ULL); ok(ENC_vcvt_u32_f64);
	eq("s5", sget(5), 0);
	ck((C.fpscr & N2AFP_IOC) != 0, "IOC set", C.fpscr & CUM, 0);

	begin("VCVT.S32.F32 1e10 saturates");
	sset(1, 0x501502F9); ok(ENC_vcvt_s32_f32);
	eq("s0", sget(0), 0x7FFFFFFFu); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVT.S32.F32 -1e10 saturates");
	sset(1, 0xD01502F9); ok(ENC_vcvt_s32_f32);
	eq("s0", sget(0), 0x80000000u); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVT.S32.F32 NaN");
	sset(1, 0x7FC00000); ok(ENC_vcvt_s32_f32); eq("s0", sget(0), 0); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	/* FPSCR-mode conversion (VCVTR) */
	begin("VCVTR.S32.F32 2.5 RN ties even");
	C.fpscr = 0u << 22; sset(7, 0x40200000); ok(ENC_vcvtr_s32_f32);
	eq("s6", sget(6), 2); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVTR.S32.F32 3.5 RN ties even");
	C.fpscr = 0u << 22; sset(7, 0x40600000); ok(ENC_vcvtr_s32_f32);
	eq("s6", sget(6), 4);

	begin("VCVTR.S32.F32 2.3 RP");
	C.fpscr = 1u << 22; sset(7, 0x40133333); ok(ENC_vcvtr_s32_f32);
	eq("s6", sget(6), 3); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVTR.S32.F32 -2.3 RM");
	C.fpscr = 2u << 22; sset(7, 0xC0133333); ok(ENC_vcvtr_s32_f32);
	eq("s6", sget(6), 0xFFFFFFFDu);

	begin("VCVTR.S32.F32 2.9 RZ");
	C.fpscr = 3u << 22; sset(7, 0x4039999A); ok(ENC_vcvtr_s32_f32);
	eq("s6", sget(6), 2);

	begin("VCVTR.U32.F32 2.7 RN");
	C.fpscr = 0u << 22; sset(9, 0x402CCCCD); ok(ENC_vcvtr_u32_f32);
	eq("s8", sget(8), 3);

	begin("VCVTR.S32.F64 2.5 RP");
	C.fpscr = 1u << 22; dset(3, 0x4004000000000000ULL); ok(ENC_vcvtr_s32_f64);
	eq("s10", sget(10), 3);

	begin("VCVTR.U32.F64 2.5 RM");
	C.fpscr = 2u << 22; dset(4, 0x4004000000000000ULL); ok(ENC_vcvtr_u32_f64);
	eq("s11", sget(11), 2);

	/* integer -> FP */
	begin("VCVT.F32.S32 7");
	sset(13, 7); ok(ENC_vcvt_f32_s32); eq("s12", sget(12), 0x40E00000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.U32 0x80000000");
	sset(15, 0x80000000u); ok(ENC_vcvt_f32_u32); eq("s14", sget(14), 0x4F000000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.S32 0x7FFFFFFF inexact");
	sset(13, 0x7FFFFFFF); ok(ENC_vcvt_f32_s32); eq("s12", sget(12), 0x4F000000);
	eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVT.F64.S32 -3");
	sset(1, 0xFFFFFFFD); ok(ENC_vcvt_f64_s32); eq("d8", dget(8), 0xC008000000000000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F64.U32 0xFFFFFFFF");
	sset(2, 0xFFFFFFFFu); ok(ENC_vcvt_f64_u32); eq("d9", dget(9), 0x41EFFFFFFFE00000ULL); eq("flags", C.fpscr & CUM, 0);

	/* fixed point */
	begin("VCVT.F32.S16 100/4");
	sset(0, 100); ok(ENC_vcvt_f32_s16); eq("s0", sget(0), 0x41C80000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.U16 65535/8");
	sset(1, 65535); ok(ENC_vcvt_f32_u16); eq("s1", sget(1), 0x45FFFF00); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.S32 -128/128");
	sset(2, 0xFFFFFF80u); ok(ENC_vcvt_f32_s32_fx); eq("s2", sget(2), 0xBF800000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F32.U32 0xFFFFFFFF/256 inexact");
	sset(3, 0xFFFFFFFFu); ok(ENC_vcvt_f32_u32_fx); eq("s3", sget(3), 0x4B800000);
	eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVT.F64.S16 -100/4");
	dset(0, 0xFFFFFF9Cu); ok(ENC_vcvt_f64_s16); eq("d0", dget(0), 0xC039000000000000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F64.U32 0xFFFFFFFF/1024");
	dset(1, 0xFFFFFFFFu); ok(ENC_vcvt_f64_u32_fx); eq("d1", dget(1), 0x414FFFFFFFE00000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.S16.F32 25*4");
	sset(4, 0x41C80000); ok(ENC_vcvt_s16_f32); eq("s4", sget(4), 100); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.U16.F32 8191.875*8");
	sset(5, 0x45FFFF00); ok(ENC_vcvt_u16_f32); eq("s5", sget(5), 65535); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.S32.F32 -1*128");
	sset(6, 0xBF800000); ok(ENC_vcvt_s32_f32_fx); eq("s6", sget(6), 0xFFFFFF80u); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.U32.F32 16777215*256");
	sset(7, 0x4B7FFFFF); ok(ENC_vcvt_u32_f32_fx); eq("s7", sget(7), 0xFFFFFF00u); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.S16.F64 1000.5*16 RN");
	dset(2, 0x408F440000000000ULL); ok(ENC_vcvt_s16_f64); eq("d2 low", C.d[2].u32[0], 16008); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.U32.F64 2.5*512");
	dset(3, 0x4004000000000000ULL); ok(ENC_vcvt_u32_f64_fx); eq("d3 low", C.d[3].u32[0], 1280); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.S32.F64 -2.5*8");
	dset(4, 0xC004000000000000ULL); ok(ENC_vcvt_s32_f64_fx); eq("d4 low", C.d[4].u32[0], 0xFFFFFFECu); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.F64.S32 7/32");
	dset(5, 7); ok(ENC_vcvt_f64_s32b); eq("d5", dget(5), 0x3FCC000000000000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VCVT.S16.F32 20000*4 saturates");
	sset(4, 0x469C4000); ok(ENC_vcvt_s16_f32);
	eq("s4 low16", sget(4) & 0xFFFFu, 32767); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVT.S16.F32 1000.53125*16 rounding RP");
	C.fpscr = 1u << 22; sset(4, 0x447A2200);	/* 1000.53125 = 0x447A2200 */
	ok(ENC_vcvt_s16_f32);
	eq("s4 low16", sget(4) & 0xFFFFu, 4003); eq("flags", C.fpscr & CUM, N2AFP_IXC);
}

/* ------------------------------------------------------------------ half precision */

static void t_half(void)
{
	begin("VCVTB.F32.F16 1.0");
	sset(1, 0x00003C00); ok(ENC_vcvtb_f32_f16); eq("s0", sget(0), 0x3F800000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVTT.F32.F16 -2.0");
	sset(3, 0xC0001111); ok(ENC_vcvtt_f32_f16); eq("s2", sget(2), 0xC0000000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVTB.F32.F16 2^-24 subnormal");
	sset(9, 0x00000001); ok(ENC_vcvtb_f32_f16_hi); eq("s8", sget(8), 0x33800000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVTT.F32.F16 qNaN");
	sset(3, 0x7E000000); ok(ENC_vcvtt_f32_f16); eq("s2", sget(2), 0x7FC00000); eq("flags", C.fpscr & CUM, 0);

	begin("VCVTT.F32.F16 sNaN");
	sset(3, 0x7C010000); ok(ENC_vcvtt_f32_f16); eq("s2", sget(2), 0x7FC02000); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVTB.F32.F16 +inf");
	sset(1, 0x00007C00); ok(ENC_vcvtb_f32_f16); eq("s0", sget(0), 0x7F800000);

	begin("VCVTB.F16.F32 1.0");
	sset(5, 0x3F800000); sset(4, 0x12345678);
	ok(ENC_vcvtb_f16_f32); eq("s4", sget(4), 0x12343C00); eq("flags", C.fpscr & CUM, 0);

	begin("VCVTT.F16.F32 1.5 (s6,s7)");
	sset(7, 0x3FC00000); sset(6, 0x12345678);
	ok(ENC_vcvtt_f16_f32);
	eq("s6", sget(6), 0x3E005678); eq("flags", C.fpscr & CUM, 0);

	begin("VCVTB.F32.F16 DN=1 sNaN sets IOC");
	C.fpscr = N2AFP_DN; sset(1, 0x7C01);
	ok(ENC_vcvtb_f32_f16);
	eq("s0", sget(0), 0x7FC00000);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVTB.F16.F32 DN=1 sNaN sets IOC");
	C.fpscr = N2AFP_DN; sset(5, 0x7F800001); sset(4, 0);
	ok(ENC_vcvtb_f16_f32);
	eq("s4 low16", sget(4) & 0xFFFFu, 0x7E00);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVTB.F16.F32 overflow");
	sset(5, 0x4E6E6B28);	/* 1e9 */
	ok(ENC_vcvtb_f16_f32); eq("s4 low16", sget(4) & 0xFFFFu, 0x7C00);
	eq("flags", C.fpscr & CUM, N2AFP_OFC | N2AFP_IXC);

	begin("VCVTB.F16.F32 2^-24 exact");
	sset(5, 0x33800000); ok(ENC_vcvtb_f16_f32); eq("s4 low16", sget(4) & 0xFFFFu, 0x0001);
	eq("flags", C.fpscr & CUM, 0);

	begin("VCVTB.F16.F32 2^-25 ties even to zero");
	sset(5, 0x33000000); ok(ENC_vcvtb_f16_f32); eq("s4 low16", sget(4) & 0xFFFFu, 0x0000);
	eq("flags", C.fpscr & CUM, N2AFP_UFC | N2AFP_IXC);

	begin("VCVTB.F16.F32 qNaN payload");
	sset(5, 0x7FC12345); ok(ENC_vcvtb_f16_f32); eq("s4 low16", sget(4) & 0xFFFFu, 0x7E09);
	eq("flags", C.fpscr & CUM, 0);

	begin("VCVTB.F16.F32 sNaN quiets");
	sset(5, 0x7F800001); ok(ENC_vcvtb_f16_f32); eq("s4 low16", sget(4) & 0xFFFFu, 0x7E00);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVTB.F16.F32 DN=1 qNaN");
	C.fpscr = N2AFP_DN; sset(5, 0x7FC12345);
	ok(ENC_vcvtb_f16_f32); eq("s4 low16", sget(4) & 0xFFFFu, 0x7E00);
}

/* ------------------------------------------------------------------ ARMv8 VSEL / VMAXNM / VMINNM */

static void t_armv8_sel(void)
{
	begin("VSEL EQ true selects Vn (APSR.Z=1, FPSCR.Z=0)");
	C.fpscr = 0; C.z = 1; sset(1, 0x11111111); sset(2, 0x22222222);
	ok(ENC_vseleq_f32); eq("s0", sget(0), 0x11111111);

	begin("VSEL EQ false selects Vm (APSR.Z=0, FPSCR.Z=1)");
	C.fpscr = 0x40000000u; C.z = 0; sset(1, 0x11111111); sset(2, 0x22222222);
	ok(ENC_vseleq_f32); eq("s0", sget(0), 0x22222222);

	begin("VSEL VS true (APSR.V=1, FPSCR.V=0)");
	C.fpscr = 0; C.v = 1; sset(4, 0x33333333); sset(5, 0x44444444);
	ok(ENC_vselvs_f32); eq("s3", sget(3), 0x33333333);

	begin("VSEL GE true (APSR N==V, FPSCR N!=V)");
	C.fpscr = 0x80000000u; C.n = 1; C.v = 1; sset(7, 0x55555555); sset(8, 0x66666666);
	ok(ENC_vselge_f32); eq("s6", sget(6), 0x55555555);

	begin("VSEL GE false (APSR N!=V, FPSCR N==V)");
	C.fpscr = 0x90000000u; C.n = 0; C.v = 1; sset(7, 0x55555555); sset(8, 0x66666666);
	ok(ENC_vselge_f32); eq("s6", sget(6), 0x66666666);

	begin("VSEL GT true (APSR Z=0 N==V, FPSCR Z=1)");
	C.fpscr = 0x40000000u; C.z = 0; sset(10, 0x77777777); sset(11, 0x88888888);
	ok(ENC_vselgt_f32); eq("s9", sget(9), 0x77777777);

	begin("VSEL GT false when APSR.Z=1 (FPSCR.Z=0)");
	C.fpscr = 0; C.z = 1; sset(10, 0x77777777); sset(11, 0x88888888);
	ok(ENC_vselgt_f32); eq("s9", sget(9), 0x88888888);

	begin("VSEL.F64 EQ (APSR.Z=1, FPSCR.Z=0)");
	C.fpscr = 0; C.z = 1; dset(1, 0x0123456789ABCDEFULL); dset(2, 0xFEDCBA9876543210ULL);
	ok(ENC_vseleq_f64); eq("d0", dget(0), 0x0123456789ABCDEFULL);

	begin("VSEL.F64 GE true (APSR N==V, FPSCR N!=V)");
	C.fpscr = 0x80000000u; C.n = 0; C.v = 0; dset(4, 0x1111222233334444ULL); dset(5, 0x5555666677778888ULL);
	ok(ENC_vselge_f64); eq("d3", dget(3), 0x1111222233334444ULL);

	begin("VSEL.F64 GT true, D extension (APSR N==V Z=0)");
	C.fpscr = 0; C.n = 1; C.v = 1; C.z = 0; dset(17, 0xAAAABBBBCCCCDDDDULL); dset(18, 0x9999888877776666ULL);
	ok(ENC_vselgt_f64); eq("d16", dget(16), 0xAAAABBBBCCCCDDDDULL);

	begin("VSEL VS false, D extension (APSR.V=0, FPSCR.V=1)");
	C.fpscr = 0x10000000u; C.v = 0; dset(7, 0x1111111111111111ULL); dset(8, 0x2222222222222222ULL);
	ok(ENC_vselvs_f64); eq("d6", dget(6), 0x2222222222222222ULL);

	/* VMAXNM / VMINNM */
	begin("VMAXNM.F32 1,2");
	sset(1, 0x3F800000); sset(2, 0x40000000); ok(ENC_vmaxnm_f32);
	eq("s0", sget(0), 0x40000000); eq("flags", C.fpscr & CUM, 0);

	begin("VMINNM.F32 1,2");
	sset(4, 0x3F800000); sset(5, 0x40000000); ok(ENC_vminnm_f32); eq("s3", sget(3), 0x3F800000);

	begin("VMAXNM.F32 +0,-0");
	sset(13, 0x00000000); sset(14, 0x80000000); ok(ENC_vmaxnm_f32_hi); eq("s12", sget(12), 0x00000000);

	begin("VMINNM.F64 +0,-0");
	dset(17, 0x0000000000000000ULL); dset(18, 0x8000000000000000ULL);
	ok(ENC_vminnm_f64_hi); eq("d16", dget(16), 0x8000000000000000ULL);

	begin("VMAXNM.F32 qNaN,2");
	sset(1, 0x7FC12345); sset(2, 0x40000000); ok(ENC_vmaxnm_f32);
	eq("s0", sget(0), 0x40000000); eq("flags", C.fpscr & CUM, 0);

	begin("VMAXNM.F32 sNaN,2");
	sset(1, 0x7F812345); sset(2, 0x40000000); ok(ENC_vmaxnm_f32);
	eq("s0", sget(0), 0x40000000); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VMAXNM.F32 qNaN,qNaN");
	sset(1, 0x7FC11111); sset(2, 0x7FC22222); ok(ENC_vmaxnm_f32); eq("s0", sget(0), 0x7FC11111);

	begin("VMAXNM.F32 NaN,NaN DN=1");
	C.fpscr = N2AFP_DN; sset(1, 0x7FC11111); sset(2, 0x7FC22222);
	ok(ENC_vmaxnm_f32); eq("s0", sget(0), 0x7FC00000);

	begin("VMINNM.F64 3,2");
	dset(4, 0x4008000000000000ULL); dset(5, 0x4000000000000000ULL);
	ok(ENC_vminnm_f64); eq("d3", dget(3), 0x4000000000000000ULL);
}

/* ------------------------------------------------------------------ ARMv8 VRINT */

static void t_vrint(void)
{
	un32("VRINTA.F32 2.5", ENC_vrinta_f32, 0, 1, 0x40200000, 0x40400000, 0);
	un32("VRINTA.F32 -2.5", ENC_vrinta_f32, 0, 1, 0xC0200000, 0xC0400000, 0);
	un32("VRINTN.F32 2.5 ties even", ENC_vrintn_f32, 2, 3, 0x40200000, 0x40000000, 0);
	un32("VRINTN.F32 3.5 ties even", ENC_vrintn_f32, 2, 3, 0x40600000, 0x40800000, 0);
	un32("VRINTN.F32 -2.5 ties even", ENC_vrintn_f32, 2, 3, 0xC0200000, 0xC0000000, 0);
	un32("VRINTP.F32 2.3", ENC_vrintp_f32, 4, 5, 0x40133333, 0x40400000, 0);
	un32("VRINTP.F32 -2.3", ENC_vrintp_f32, 4, 5, 0xC0133333, 0xC0000000, 0);
	un32("VRINTM.F32 -2.3", ENC_vrintm_f32, 6, 7, 0xC0133333, 0xC0400000, 0);
	un32("VRINTM.F32 2.3", ENC_vrintm_f32, 6, 7, 0x40133333, 0x40000000, 0);
	un32("VRINTZ.F32 -2.7", ENC_vrintz_f32, 10, 11, 0xC02CCCCD, 0xC0000000, 0);
	un32("VRINTZ.F32 -0.4 keeps -0", ENC_vrintz_f32, 10, 11, 0xBE4CCCCD, 0x80000000, 0);
	un32("VRINTX.F32 2.5 RN inexact", ENC_vrintx_f32, 8, 9, 0x40200000, 0x40000000, N2AFP_IXC);
	un32("VRINTX.F32 2.0 RN exact", ENC_vrintx_f32, 8, 9, 0x40000000, 0x40000000, 0);
	un32("VRINTX.F32 -2.5 RN inexact", ENC_vrintx_f32, 8, 9, 0xC0200000, 0xC0000000, N2AFP_IXC);
	un32("VRINTZ.F32 sNaN", ENC_vrintz_f32, 10, 11, 0x7F812345, 0x7FC12345, N2AFP_IOC);
	un64("VRINTA.F64 2.5", ENC_vrinta_f64, 0, 1, 0x4004000000000000ULL, 0x4008000000000000ULL, 0);
	un64("VRINTN.F64 2.5", ENC_vrintn_f64, 2, 3, 0x4004000000000000ULL, 0x4000000000000000ULL, 0);
	un64("VRINTN.F64 -2.5", ENC_vrintn_f64, 2, 3, 0xC004000000000000ULL, 0xC000000000000000ULL, 0);
	un64("VRINTP.F64 -2.3", ENC_vrintp_f64, 4, 5, 0xC002666666666666ULL, 0xC000000000000000ULL, 0);
	un64("VRINTM.F64 -2.3", ENC_vrintm_f64, 6, 7, 0xC002666666666666ULL, 0xC008000000000000ULL, 0);
	un64("VRINTX.F64 2.5", ENC_vrintx_f64, 8, 9, 0x4004000000000000ULL, 0x4000000000000000ULL, N2AFP_IXC);
	un64("VRINTZ.F64 -2.7", ENC_vrintz_f64, 10, 11, 0xC00599999999999AULL, 0xC000000000000000ULL, 0);
	un64("VRINTM.F64 +inf", ENC_vrintm_f64, 6, 7, 0x7FF0000000000000ULL, 0x7FF0000000000000ULL, 0);

	begin("VRINTR.F32 RMode RP 2.1");
	C.fpscr = 1u << 22; sset(13, 0x40066666); ok(ENC_vrintr_f32);
	eq("s12", sget(12), 0x40400000); eq("flags", C.fpscr & CUM, 0);

	begin("VRINTR.F64 RMode RM -2.1");
	C.fpscr = 2u << 22; dset(13, 0xC000CCCCCCCCCCCDULL); ok(ENC_vrintr_f64);
	eq("d12", dget(12), 0xC008000000000000ULL); eq("flags", C.fpscr & CUM, 0);

	begin("VRINTX.F32 RMode RP 2.1 sets IXC");
	C.fpscr = 1u << 22; sset(9, 0x40066666); ok(ENC_vrintx_f32);
	eq("s8", sget(8), 0x40400000); eq("flags", C.fpscr & CUM, N2AFP_IXC);
}

/* ------------------------------------------------------------------ ARMv8 VCVTA/N/P/M */

static void t_vcvta(void)
{
	begin("VCVTA.S32.F32 2.5");
	sset(1, 0x40200000); ok(ENC_vcvta_s32_f32); eq("s0", sget(0), 3); eq("flags", C.fpscr & CUM, N2AFP_IXC);

	begin("VCVTA.S32.F32 -2.5");
	sset(1, 0xC0200000); ok(ENC_vcvta_s32_f32); eq("s0", sget(0), 0xFFFFFFFDu);

	begin("VCVTN.S32.F32 2.5");
	sset(3, 0x40200000); ok(ENC_vcvtn_s32_f32); eq("s2", sget(2), 2);

	begin("VCVTN.S32.F32 3.5");
	sset(3, 0x40600000); ok(ENC_vcvtn_s32_f32); eq("s2", sget(2), 4);

	begin("VCVTP.S32.F32 2.3");
	sset(5, 0x40133333); ok(ENC_vcvtp_s32_f32); eq("s4", sget(4), 3);

	begin("VCVTM.S32.F32 -2.3");
	sset(7, 0xC0133333); ok(ENC_vcvtm_s32_f32); eq("s6", sget(6), 0xFFFFFFFDu);

	begin("VCVTA.U32.F32 2.5");
	sset(9, 0x40200000); ok(ENC_vcvta_u32_f32); eq("s8", sget(8), 3);

	begin("VCVTN.U32.F32 -2.5 saturates");
	sset(11, 0xC0200000); ok(ENC_vcvtn_u32_f32); eq("s10", sget(10), 0);
	ck((C.fpscr & N2AFP_IOC) != 0, "IOC set", C.fpscr & CUM, 0);

	begin("VCVTP.U32.F32 2.3");
	sset(13, 0x40133333); ok(ENC_vcvtp_u32_f32); eq("s12", sget(12), 3);

	begin("VCVTM.U32.F32 -2.3");
	sset(15, 0xC0133333); ok(ENC_vcvtm_u32_f32); eq("s14", sget(14), 0);
	ck((C.fpscr & N2AFP_IOC) != 0, "IOC set", C.fpscr & CUM, 0);

	begin("VCVTA.S32.F32 NaN");
	sset(1, 0x7FC00000); ok(ENC_vcvta_s32_f32); eq("s0", sget(0), 0); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVTA.S32.F32 1e10 saturates");
	sset(1, 0x501502F9); ok(ENC_vcvta_s32_f32); eq("s0", sget(0), 0x7FFFFFFFu);
	eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("VCVTA.S32.F64 2.5");
	dset(1, 0x4004000000000000ULL); ok(ENC_vcvta_s32_f64); eq("s0", sget(0), 3);

	begin("VCVTN.U32.F64 2.5");
	dset(2, 0x4004000000000000ULL); ok(ENC_vcvtn_u32_f64); eq("s1", sget(1), 2);

	begin("VCVTP.S32.F64 2.3");
	dset(3, 0x4002666666666666ULL); ok(ENC_vcvtp_s32_f64); eq("s2", sget(2), 3);

	begin("VCVTM.U32.F64 -2.3");
	dset(4, 0xC002666666666666ULL); ok(ENC_vcvtm_u32_f64); eq("s3", sget(3), 0);
	ck((C.fpscr & N2AFP_IOC) != 0, "IOC set", C.fpscr & CUM, 0);
}

/* ------------------------------------------------------------------ Thumb-2 twins */

static void t_t32(void)
{
	begin("T32 VLDR s0,[r0]");
	C.r[0] = 0x14000; w32(0x14000, 0xCAFEBABE);
	ok(ENC_t32_vldr_s0_r0); eq("s0", sget(0), 0xCAFEBABE);

	begin("T32 VSTR d0,[r1,#8]");
	C.r[1] = 0x14100; dset(0, 0x0123456789ABCDEFULL);
	ok(ENC_t32_vstr_d0_r1_p8); eq("mem", r64(0x14108), 0x0123456789ABCDEFULL);

	begin("T32 VLDR s1,[pc,#16]");
	w32((PC_IN & ~3u) + 16u, 0x7FC00001);
	ok(ENC_t32_vldr_s1_pc); eq("s1", sget(1), 0x7FC00001);

	begin("T32 VLDMIA r2,{d0-d1}");
	C.r[2] = 0x14200; w64(0x14200, 0x1111111111111111ULL); w64(0x14208, 0x2222222222222222ULL);
	ok(ENC_t32_vldm_r2_d0_d1); eq("d0", dget(0), 0x1111111111111111ULL);

	begin("T32 VSTMIA r3!,{s0-s1}");
	C.r[3] = 0x14300; sset(0, 0xAAAAAAAA); sset(1, 0xBBBBBBBB);
	ok(ENC_t32_vstm_r3w_s0_s1); eq("mem0", r32(0x14300), 0xAAAAAAAA); eq("r3", C.r[3], 0x14308);

	begin("T32 VPUSH {s0-s3}");
	C.r[13] = 0x14400; sset(0, 1); sset(1, 2); sset(2, 3); sset(3, 4);
	ok(ENC_t32_vpush_s0_s3); eq("sp", C.r[13], 0x143F0); eq("mem3", r32(0x143FC), 4);

	begin("T32 VPOP {d0-d1}");
	C.r[13] = 0x14500; w64(0x14500, 0x3333333333333333ULL); w64(0x14508, 0x4444444444444444ULL);
	ok(ENC_t32_vpop_d0_d1); eq("d1", dget(1), 0x4444444444444444ULL); eq("sp", C.r[13], 0x14510);

	begin("T32 VADD.F32");
	sset(1, 0x3FC00000); sset(2, 0x40100000); ok(ENC_t32_vadd_f32); eq("s0", sget(0), 0x40700000);

	begin("T32 VADD.F64");
	dset(1, 0x3FF8000000000000ULL); dset(2, 0x4002000000000000ULL);
	ok(ENC_t32_vadd_f64); eq("d0", dget(0), 0x400E000000000000ULL);

	begin("T32 VSUB.F64 high registers");
	dset(11, 0x3FF8000000000000ULL); dset(12, 0x4002000000000000ULL);
	ok(ENC_t32_vsub_f64); eq("d10", dget(10), 0xBFE8000000000000ULL);

	begin("T32 VMUL.F64");
	dset(1, 0x4008000000000000ULL); dset(2, 0x4000000000000000ULL);
	ok(ENC_t32_vmul_f64); eq("d0", dget(0), 0x4018000000000000ULL);

	begin("T32 VDIV.F32 1/0");
	sset(1, 0x3F800000); sset(2, 0); ok(ENC_t32_vdiv_f32);
	eq("s0", sget(0), 0x7F800000); eq("flags", C.fpscr & CUM, N2AFP_DZC);

	begin("T32 VMLA.F64");
	dset(1, 0x4008000000000000ULL); dset(2, 0x4010000000000000ULL); dset(0, 0x4000000000000000ULL);
	ok(ENC_t32_vmla_f64); eq("d0", dget(0), 0x402C000000000000ULL);

	begin("T32 VFMA.F32");
	sset(1, 0x40400000); sset(2, 0x40800000); sset(0, 0x40000000);
	ok(ENC_t32_vfma_f32); eq("s0", sget(0), 0x41600000);

	begin("T32 VABS.F32");
	sset(1, 0xBFC00000); ok(ENC_t32_vabs_f32); eq("s0", sget(0), 0x3FC00000);

	begin("T32 VNEG.F64");
	dset(1, 0x3FF0000000000000ULL); ok(ENC_t32_vneg_f64); eq("d0", dget(0), 0xBFF0000000000000ULL);

	begin("T32 VSQRT.F64");
	dset(1, 0x4010000000000000ULL); ok(ENC_t32_vsqrt_f64); eq("d0", dget(0), 0x4000000000000000ULL);

	begin("T32 VCMP.F32");
	sset(0, 0x3F800000); sset(1, 0x40000000); ok(ENC_t32_vcmp_f32);
	eq("nzcv", C.fpscr & 0xF0000000u, 0x80000000);

	begin("T32 VCMPE.F64 qNaN");
	dset(0, 0x7FF8000000000000ULL); dset(1, 0x3FF0000000000000ULL); ok(ENC_t32_vcmpe_f64);
	eq("nzcv", C.fpscr & 0xF0000000u, 0x30000000); eq("flags", C.fpscr & CUM, N2AFP_IOC);

	begin("T32 VMOV r0,s0");
	sset(0, 0xDEADBEEF); ok(ENC_t32_vmov_r0_s0); eq("r0", C.r[0], 0xDEADBEEF);

	begin("T32 VMOV s0,r0");
	C.r[0] = 0x0BADF00D; ok(ENC_t32_vmov_s0_r0); eq("s0", sget(0), 0x0BADF00D);

	begin("T32 VMOV d0,r0,r1");
	C.r[0] = 0x11111111; C.r[1] = 0x22222222; ok(ENC_t32_vmov_d0_r0_r1);
	eq("d0", dget(0), 0x2222222211111111ULL);

	begin("T32 VMOV r2,r3,d0");
	dset(0, 0xAAAABBBBCCCCDDDDULL); ok(ENC_t32_vmov_r2_r3_d0);
	eq("r2", C.r[2], 0xCCCCDDDD); eq("r3", C.r[3], 0xAAAABBBB);

	begin("T32 VMOV.32 r0,d0[1]");
	dset(0, 0x1122334455667788ULL); ok(ENC_t32_vmov_32_r0_d0_1); eq("r0", C.r[0], 0x11223344);

	begin("T32 VMOV.U8 r1,d1[2]");
	dset(1, 0x0000000000FF0000ULL); ok(ENC_t32_vmov_u8_r1_d1_2); eq("r1", C.r[1], 0xFF);

	begin("T32 VDUP.32 d0,r0");
	C.r[0] = 0x12345678; ok(ENC_t32_vdup_32_d0_r0); eq("d0", dget(0), 0x1234567812345678ULL);

	begin("T32 VMRS APSR_nzcv");
	C.fpscr = 0x30000000; ok(ENC_t32_vmrs_apsr); eq("z", C.z, 0); eq("c", C.cf, 1); eq("v", C.v, 1);

	begin("T32 VMSR FPSCR");
	C.r[0] = 0x0000001F; ok(ENC_t32_vmsr_r0); eq("fpscr", C.fpscr, 0x1F);

	begin("T32 VCVT.F64.S32");
	sset(0, 7); ok(ENC_t32_vcvt_f64_s32); eq("d0", dget(0), 0x401C000000000000ULL);

	begin("T32 VCVT.S32.F64");
	dset(0, 0x4004000000000000ULL); ok(ENC_t32_vcvt_s32_f64); eq("s0", sget(0), 2);

	begin("T32 VCVT.F32.F64");
	dset(0, 0x4004000000000000ULL); ok(ENC_t32_vcvt_f32_f64); eq("s0", sget(0), 0x40200000);

	begin("T32 VCVT.F64.F32");
	sset(0, 0x3FC00000); ok(ENC_t32_vcvt_f64_f32); eq("d0", dget(0), 0x3FF8000000000000ULL);

	begin("T32 VMOV.F32 #1.0");
	ok(ENC_t32_vmov_f32_imm); eq("s0", sget(0), 0x3F800000);

	begin("T32 VMOV.F64 #-2.5");
	ok(ENC_t32_vmov_f64_imm); eq("d0", dget(0), 0xC004000000000000ULL);

	begin("T32 VSEL EQ (APSR.Z=1, FPSCR.Z=0)");
	C.fpscr = 0; C.z = 1; sset(1, 0xAAAAAAAA); sset(2, 0xBBBBBBBB);
	ok(ENC_t32_vseleq_f32); eq("s0", sget(0), 0xAAAAAAAA);

	begin("T32 VMAXNM.F32");
	sset(1, 0x3F800000); sset(2, 0x40000000); ok(ENC_t32_vmaxnm_f32); eq("s0", sget(0), 0x40000000);

	begin("T32 VRINTA.F64");
	dset(1, 0x4004000000000000ULL); ok(ENC_t32_vrinta_f64); eq("d0", dget(0), 0x4008000000000000ULL);

	begin("T32 VRINTZ.F32");
	sset(1, 0xC02CCCCD); ok(ENC_t32_vrintz_f32); eq("s0", sget(0), 0xC0000000);

	begin("T32 VCVTA.S32.F32");
	sset(1, 0x40200000); ok(ENC_t32_vcvta_s32_f32); eq("s0", sget(0), 3);

	begin("T32 VCVTB.F32.F16");
	sset(1, 0x00003C00); ok(ENC_t32_vcvtb_f32_f16); eq("s0", sget(0), 0x3F800000);

	begin("T32 VCVTT.F16.F32");
	sset(1, 0x3FC00000); sset(0, 0x12345678); ok(ENC_t32_vcvtt_f16_f32);
	eq("s0", sget(0), 0x3E005678);

	begin("T32 FLDMIAX r0,{d0-d1}");
	C.r[0] = 0x14600;
	w64(0x14600, 0x1111111111111111ULL); w64(0x14608, 0x2222222222222222ULL); w32(0x14610, 1);
	ok(ENC_t32_fldmiax_r0); eq("d1", dget(1), 0x2222222222222222ULL); eq("fpscr", C.fpscr, 1);

	begin("T32 FSTMIAX r1,{d0-d1}");
	C.r[1] = 0x14700; dset(0, 1); dset(1, 2); C.fpscr = 0x10;
	ok(ENC_t32_fstmiax_r1); eq("mem1", r64(0x14708), 2); eq("extra", r32(0x14710), 0x10);
}

